// The one sanctioned shortcut: "buy me <Apple hardware>" with no store named → Apple's online store.
// All product knowledge lives in data/apple-catalog.json (generated by npm run refresh-apple-catalog
// from Apple's live store, marked SANCTIONED EXCEPTION). This file only matches words against it:
// a family name must appear whole ("air pods" = "AirPods", "AirPods Pro 3" → AirPods); "apples",
// "a phone" or "headphones" never match. "a case for my iPhone" asks whose case you mean.

import { tokens } from './interpret.js';

const sing = (w) => w.replace(/s$/, '');
const squash = (s) => tokens(s).map(sing).join('');

export function makeCatalog(data, { now = Date.now() } = {}) {
  if (!data?.families?.length || !data.storeURL) return null;
  // A family also answers to its base name: "Apple Watch Series 12" → "Apple Watch", "iPhone 18 Pro" → "iPhone"
  // (new generations and models are covered without editing the catalog).
  const base = (n) => n.replace(/\s+(\d+[a-z]?|series \d+|ultra( \d+)?|pro|max|mini( \d+)?|air|plus|duo|4k|se)$/i, '').trim();
  const bases = (n) => { const out = [n]; for (let b = base(n); b !== out.at(-1) && b; b = base(b)) out.push(b); return out; };
  const families = data.families.map((f) => ({ ...f, keys: [...new Set([f.name, ...bases(f.name), ...(f.aliases ?? [])].map(squash).filter((k) => k.length > 3))] }))
    .sort((a, b) => Math.max(...b.keys.map((k) => k.length)) - Math.max(...a.keys.map((k) => k.length)));
  const ageDays = data.refreshed ? (now - Date.parse(data.refreshed)) / 864e5 : Infinity;
  if (ageDays > 30) console.warn(`[catalog] Apple catalog is ${Math.round(ageDays)} days old; run npm run refresh-apple-catalog`);
  return {
    storeURL: data.storeURL,
    stale: ageDays > 30,
    names: data.families.map((f) => f.name),  // for speech recognition: "HomePod", not "home view"
    /**
     * {family, url?} | {ask} | null. Of every family whose name (or base name) was said, the closest:
     * most of your words in its full name, then fewest of its words you didn't say ("AirPod 3s" →
     * AirPods Pro 3, not AirPods Max 2). url = its own store page, only when its full name was said.
     */
    match(item) {
      const w = tokens(item).map(sing);
      let best = null;
      for (const f of families) {
        for (let i = 0; i < w.length; i++) {
          for (let j = i; j < Math.min(w.length, i + 4); j++) {
            if (!f.keys.includes(w.slice(i, j + 1).join(''))) continue;
            // "a charger for my iPhone": an accessory FOR the product — whose accessory?
            if (w.slice(0, i).some((x) => x === 'for' || x === 'with' || x === 'fit')) return { ask: `Do you want Apple's own one, or any brand that fits your ${f.name}?` };
            const fw = tokens(f.name).map(sing).filter((x) => x !== 'apple');
            const said = fw.filter((x) => w.includes(x) || w.join('').includes(x)).length;
            const score = said * 10 - (fw.length - said);
            if (!best || score > best.score) best = { f, score, full: said === fw.length };
          }
        }
      }
      if (!best) return null;
      let url = best.full ? best.f.url : null;
      // "AirPods Max" → the one current "AirPods Max 2" page; "iPhone" (many models, none closest) → none.
      if (best.full && !url) {
        const kids = families.filter((g) => g.url && g.name.toLowerCase().startsWith(`${best.f.name.toLowerCase()} `));
        const extra = (g) => tokens(g.name).length - tokens(best.f.name).length;
        const fewest = Math.min(...kids.map(extra));
        const closest = kids.filter((g) => extra(g) === fewest);
        if (closest.length === 1) url = closest[0].url;
      }
      return url ? { family: best.f.name, url } : { family: best.f.name };
    },
  };
}
